// ============================================================================
// Azure Data Factory resource configuration
// ============================================================================
let SubscriptionId = "262a3c1d-7fe3-4bfb-9f90-7a5b89109336";
let ResourceGroup  = "Idea2.0";
let DataFactoryName = "pf-observability-datafactory";

let FactoryResourceId = strcat(
    "/subscriptions/", SubscriptionId,
    "/resourceGroups/", ResourceGroup,
    "/providers/Microsoft.DataFactory/factories/", DataFactoryName
);

// ============================================================================
// Final row per RunId within the selected Grafana time window
// ============================================================================
let FinalRuns =
    ADFPipelineRun
    | extend
        TG = todatetime(TimeGenerated),
        Start_dt = todatetime(Start)
    | where $__timeFilter(TG)
    | summarize arg_max(TG, *) by RunId;

// ============================================================================
// Latest run for each pipeline
// ============================================================================
let LatestPerPipeline =
    FinalRuns
    | summarize arg_max(Start_dt, *) by PipelineName
    | project
        PipelineName,
        LatestRun_Start = Start_dt,
        LatestRun_Status = Status,
        LatestRun_RunId = RunId;

// ============================================================================
// Previous completed run
// ============================================================================
let Prev1_ByPipeline =
    FinalRuns
    | where Status in ("Succeeded", "Failed")
    | join kind=inner (
        LatestPerPipeline
        | project PipelineName, LatestRun_Start
    ) on PipelineName
    | where Start_dt < LatestRun_Start
    | summarize PrevRun1_Start = max(Start_dt) by PipelineName;

let Prev1_WithStatus =
    Prev1_ByPipeline
    | join kind=leftouter (
        FinalRuns
        | project PipelineName, Start_dt, Status
    ) on PipelineName
    | where Start_dt == PrevRun1_Start
    | project
        PipelineName,
        PrevRun1_Start,
        PrevRun1_Status = Status;

// ============================================================================
// Second previous completed run
// ============================================================================
let Prev2_ByPipeline =
    Prev1_WithStatus
    | join kind=inner (
        FinalRuns
        | where Status in ("Succeeded", "Failed")
        | project PipelineName, Start_dt, Status
    ) on PipelineName
    | where Start_dt < PrevRun1_Start
    | summarize PrevRun2_Start = max(Start_dt) by PipelineName;

let Prev2_WithStatus =
    Prev2_ByPipeline
    | join kind=leftouter (
        FinalRuns
        | project PipelineName, Start_dt, Status
    ) on PipelineName
    | where Start_dt == PrevRun2_Start
    | project
        PipelineName,
        PrevRun2_Start,
        PrevRun2_Status = Status;

// ============================================================================
// Final Grafana table
// ============================================================================
LatestPerPipeline
| join kind=leftouter Prev1_WithStatus on PipelineName
| join kind=leftouter Prev2_WithStatus on PipelineName
| extend ADFUrl = strcat(
    "https://adf.azure.com/en/authoring/pipeline/",
    tostring(PipelineName),
    "?factory=",
    FactoryResourceId
)
| project
    PipelineName,
    LatestRun_Start,
    LatestRun_Status,
    PrevRun1_Start,
    PrevRun1_Status,
    PrevRun2_Start,
    PrevRun2_Status,
    ADFUrl
| order by PipelineName asc
